code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long m = sc.nextLong();

        long hours = m / 60;
        long minutes = m % 60;
        System.out.println(hours + " hours " + minutes + " minutes");
    }
}
